package com.saivandan.crm.api;
import com.saivandan.crm.domain.*; import com.saivandan.crm.repo.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/dashboard") public class DashboardController { private final LeadRepository leads; private final PropertyUnitRepository units; private final BookingRepository bookings; public DashboardController(LeadRepository l,PropertyUnitRepository u,BookingRepository b){leads=l;units=u;bookings=b;} @GetMapping public Map<String,Object> summary(){return Map.of("totalLeads",leads.count(),"newLeads",leads.countByStatus(LeadStatus.NEW),"qualifiedLeads",leads.countByStatus(LeadStatus.QUALIFIED),"availableUnits",units.countByStatus(UnitStatus.AVAILABLE),"soldUnits",units.countByStatus(UnitStatus.SOLD),"bookings",bookings.count());} }
